77		cosD, sinD := math.Cos(dHeading), math.Sin(dHeading)
78	
79		// ---- 在副本上推演新位姿，真实状态此时保持不变 ----
80		next := append([]Pose(nil), st.trajectory...)
81		accumVar := tgt.Variance
82		for j := anchorIdx; j <= end; j++ {
83			old := st.trajectory[j]
84			if j > anchorIdx {
85				accumVar += st.sources[j-1].moveVariance
86			}
87			dx := old.X - oldAnchor.X
88			dy := old.Y - oldAnchor.Y
89			np := Pose{
90				Time:     old.Time,
91				X:        tgt.X + cosD*dx - sinD*dy,
92				Y:        tgt.Y + sinD*dx + cosD*dy,
93				Heading:  normalizeAngle(old.Heading + dHeading),
94				Variance: accumVar,
95			}
96			if !isFinite(np.X) || !isFinite(np.Y) || !isFinite(np.Heading) || !isFinite(np.Variance) {
97				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
98			}
99			next[j] = np
100		}
101	
102		// 受影响路标：在受影响帧中被观测到的全部路标。
103		affected := make(map[string]struct{})
104		for j := anchorIdx; j <= end; j++ {
105			for _, ob := range st.sources[j-1].observations {
106				affected[ob.ID] = struct{}{}
107			}
108		}
109		affectedIDs := make([]string, 0, len(affected))
110		for id := range affected {
111			affectedIDs = append(affectedIDs, id)
112		}
113		sort.Strings(affectedIDs)
114	
115		// 逐路标运行聚合：旧文件的既有观测作为固定“旧贡献”起点（位置不
116		// 随校正改变），其余观测按帧时间与同帧输入次序、以当前/校正后位姿
117		// 重放，完整复刻导入时的增量平均与合并距离判定。
118		type agg struct {
119			count int
120			x, y  float64
121		}
122		aggs := make(map[string]*agg, len(affectedIDs))
123		for _, id := range affectedIDs {
124			lm := st.landmarks[id]
125			a := &agg{}
126			if lm != nil && lm.legacyCount > 0 {
127				a.count = lm.legacyCount
128				a.x = lm.legacyMX
129				a.y = lm.legacyMY
130			}
131			aggs[id] = a
132		}
133		for j := 1; j <= end; j++ {
134			src := st.sources[j-1]
135			if src == nil {
136				continue // 旧文件帧：观测已计入各路标 legacy 起点
137			}
138			pose := next[j]
139			for _, ob := range src.observations {
140				a, ok := aggs[ob.ID]
141				if !ok {
142					continue
143				}
144				mx, my := localToMap(pose.X, pose.Y, pose.Heading, ob.X, ob.Y)
145				if a.count > 0 && math.Hypot(mx-a.x, my-a.y) > st.config.MergeDistance {
146					return CorrectionRecord{}, &RejectError{
147						Kind:        RejectLandmarkConflict,
148						Time:        st.trajectory[j].Time,
149						HasTime:     true,
150						Landmark:    ob.ID,
151						HasLandmark: true,
152					}
153				}
154				a.x = (a.x*float64(a.count) + mx) / float64(a.count+1)
155				a.y = (a.y*float64(a.count) + my) / float64(a.count+1)
156				a.count++
157			}
158		}
159		for id, a := range aggs {
160			if !isFinite(a.x) || !isFinite(a.y) {
161				return CorrectionRecord{}, &RejectError{Kind: RejectNonFinite, Time: req.Anchor, HasTime: true}
162			}
163			if lm := st.landmarks[id]; lm == nil || a.count != lm.count {
164				// 内存不变量被破坏不可能由本包写出，按损坏处理而非半提交。
165				return CorrectionRecord{}, ErrCorrupt
166			}
167		}
168	
169		// ---- 组装校正前后快照（记录不可变） ----
170		rec := &CorrectionRecord{
171			ID:        req.ID,
172			Anchor:    req.Anchor,
173			Target:    tgt,
174			EndTime:   st.trajectory[end].Time,
175			Poses:     make([]PoseChange, 0, end-anchorIdx+1),
176			Landmarks: make([]LandmarkChange, 0, len(affectedIDs)),
177		}
178		for j := anchorIdx; j <= end; j++ {
179			rec.Poses = append(rec.Poses, PoseChange{Before: st.trajectory[j], After: next[j]})
180		}
181		for _, id := range affectedIDs {
182			lm := st.landmarks[id]
183			a := aggs[id]
184			rec.Landmarks = append(rec.Landmarks, LandmarkChange{
185				ID:     id,
186				Before: Landmark{ID: id, X: lm.x, Y: lm.y, Count: lm.count},
187				After:  Landmark{ID: id, X: a.x, Y: a.y, Count: a.count},
188			})
189		}
190	
191		// ---- 全部校验通过：暂存提交并落盘；落盘失败精确回滚 ----
192		oldTraj := append([]Pose(nil), st.trajectory...)
193		type lmSnapshot struct {
194			x, y               float64
195			count, legacyCount int
196			legacyMX, legacyMY float64
197		}
198		oldLM := make(map[string]lmSnapshot, len(affectedIDs))
199		for _, id := range affectedIDs {
200			lm := st.landmarks[id]
201			oldLM[id] = lmSnapshot{lm.x, lm.y, lm.count, lm.legacyCount, lm.legacyMX, lm.legacyMY}
202		}
203		oldCorrLen := len(st.corrections)
204	
205		st.trajectory = next
206		for _, id := range affectedIDs {
207			a := aggs[id]
208			lm := st.landmarks[id]
209			lm.x, lm.y = a.x, a.y
210		}
211		st.corrections = append(st.corrections, rec)
212		st.corrIndex[req.ID] = canonicalCorrectionHash(req.Anchor, tgt)
213	
214		if err := m.saveReplace(); err != nil {
215			st.trajectory = oldTraj
216			for id, s := range oldLM {
217				lm := st.landmarks[id]
218				lm.x, lm.y, lm.count = s.x, s.y, s.count
219				lm.legacyCount, lm.legacyMX, lm.legacyMY = s.legacyCount, s.legacyMX, s.legacyMY
220			}
221			st.corrections = st.corrections[:oldCorrLen]
222			delete(st.corrIndex, req.ID)
223			return CorrectionRecord{}, err
224		}
225		return cloneRecord(rec), nil
226	}
227	
228	// Corrections 返回按提交次序排列的成功校正记录副本。记录一经生成永不
229	// 被后续校正改写；后续校正只是以当时最新状态为起点生成新记录。
230	func (m *Map) Corrections() ([]CorrectionRecord, error) {
231		m.mu.Lock()
232		defer m.mu.Unlock()
233		if m.closed {
234			return nil, ErrClosed
235		}
236		out := make([]CorrectionRecord, 0, len(m.state.corrections))
237		for _, rec := range m.state.corrections {
238			out = append(out, cloneRecord(rec))
239		}
240		return out, nil
241	}
242	
243	func (st *mapState) correctionRecordByID(id string) *CorrectionRecord {
244		for _, rec := range st.corrections {
245			if rec.ID == id {
246				return rec
247			}
248		}
249		return nil
250	}
251	
252	func cloneRecord(rec *CorrectionRecord) CorrectionRecord {
253		if rec == nil {
254			return CorrectionRecord{}
255		}
256		cp := *rec
257		cp.Poses = append([]PoseChange(nil), rec.Poses...)
258		cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
259		return cp
260	}
