1	package posemap
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/json"
7		"fmt"
8		"hash/crc32"
9		"math"
10		"os"
11		"path/filepath"
12	)
13	
14	// 文件布局（均为大端）：
15	//
16	//	magic     8 字节  "POSEMAP1"
17	//	version   uint16
18	//	length    uint32  payload 字节数
19	//	payload   length 字节（JSON，见 fileData）
20	//	crc       uint32  对 crc 之前全部字节的 CRC-32/IEEE
21	//
22	// 保存采用“同目录临时文件写完并 fsync 后 rename”的方式，成功导入对
23	// 调用方可见时文件必为完整的新版本；无法识别或校验失败的文件绝不被
24	// 覆盖（Create 用 O_EXCL，Open 只读取证）。
25	// 文件格式在版本 1 内以“追加 JSON 字段”的方式演进：旧文件不含
26	// sources/corrections 字段（解码后为 nil/空），据此识别缺少逐帧依据的
27	// 旧地图；二进制版本号保持 1，不支持的版本号仍按既有约定拒绝。
28	const (
29		fileMagic   = "POSEMAP1"
30		fileVersion = uint16(1)
31		headerLen   = 8 + 2 + 4
32	)
33	
34	type fileData struct {
35		Version     int             `json:"version"`
36		Config      Config          `json:"config"`
37		Trajectory  []Pose          `json:"trajectory"`
38		Landmarks   []landmarkJSON  `json:"landmarks"`
39		Segments    []segmentJSON   `json:"segments"`
40		Sources     []*frameSrcJSON `json:"sources,omitempty"`     // 新格式：逐帧依据，旧帧为 null；旧文件整列缺省
41		Corrections []corrRecJSON   `json:"corrections,omitempty"` // 新格式：按提交次序的校正记录
42	}
43	
44	type landmarkJSON struct {
45		ID          string  `json:"id"`
46		X           float64 `json:"x"`
47		Y           float64 `json:"y"`
48		Count       int     `json:"count"`
49		LegacyCount int     `json:"legacy_count,omitempty"`
50		LegacyMX    float64 `json:"legacy_mx,omitempty"`
51		LegacyMY    float64 `json:"legacy_my,omitempty"`
52	}
53	
54	type segmentJSON struct {
55		ID     string       `json:"id"`
56		Hash   string       `json:"hash"`
57		Result ImportResult `json:"result"`
58	}
59	
60	type frameSrcJSON struct {
61		MoveVariance float64       `json:"move_variance"`
62		Observations []Observation `json:"observations"`
63	}
64	
65	type poseChangeJSON struct {
66		Before Pose `json:"before"`
67		After  Pose `json:"after"`
68	}
69	
70	type landmarkChangeJSON struct {
71		ID     string   `json:"id"`
72		Before Landmark `json:"before"`
73		After  Landmark `json:"after"`
74	}
75	
76	type corrRecJSON struct {
77		ID        string               `json:"id"`
78		Anchor    int64                `json:"anchor"`
79		Target    CorrectionTarget     `json:"target"`
80		EndTime   int64                `json:"end_time"`
81		Poses     []poseChangeJSON     `json:"poses"`
82		Landmarks []landmarkChangeJSON `json:"landmarks"`
83	}
84	
85	// encodeFile 把内存状态编码为完整文件字节。
86	func encodeFile(st *mapState) ([]byte, error) {
87		fd := fileData{
88			Version:     int(fileVersion),
89			Config:      st.config,
90			Trajectory:  st.trajectory,
91			Landmarks:   make([]landmarkJSON, 0, len(st.landmarks)),
92			Segments:    make([]segmentJSON, 0, len(st.segments)),
93			Sources:     make([]*frameSrcJSON, len(st.sources)),
94			Corrections: make([]corrRecJSON, 0, len(st.corrections)),
95		}
96		for id, lm := range st.landmarks {
97			fd.Landmarks = append(fd.Landmarks, landmarkJSON{
98				ID:          id,
99				X:           lm.x,
100				Y:           lm.y,
101				Count:       lm.count,
102				LegacyCount: lm.legacyCount,
103				LegacyMX:    lm.legacyMX,
104				LegacyMY:    lm.legacyMY,
105			})
106		}
107		for id, rec := range st.segments {
108			fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
109		}
110		for k, src := range st.sources {
111			if src == nil {
112				continue // 旧文件帧在新文件中保留为 null，表示仍无逐帧依据
113			}
114			obs := append([]Observation(nil), src.observations...)
115			fd.Sources[k] = &frameSrcJSON{MoveVariance: src.moveVariance, Observations: obs}
116		}
117		for _, rec := range st.corrections {
118			cj := corrRecJSON{
119				ID:        rec.ID,
120				Anchor:    rec.Anchor,
121				Target:    rec.Target,
122				EndTime:   rec.EndTime,
123				Poses:     make([]poseChangeJSON, len(rec.Poses)),
124				Landmarks: make([]landmarkChangeJSON, len(rec.Landmarks)),
125			}
126			for i, pc := range rec.Poses {
127				cj.Poses[i] = poseChangeJSON{Before: pc.Before, After: pc.After}
128			}
129			for i, lc := range rec.Landmarks {
130				cj.Landmarks[i] = landmarkChangeJSON{ID: lc.ID, Before: lc.Before, After: lc.After}
131			}
132			fd.Corrections = append(fd.Corrections, cj)
133		}
134		payload, err := json.Marshal(&fd)
135		if err != nil {
136			return nil, fmt.Errorf("posemap: encode state: %w", err)
137		}
138	
139		out := make([]byte, headerLen+len(payload)+4)
140		copy(out[0:8], fileMagic)
141		binary.BigEndian.PutUint16(out[8:10], fileVersion)
142		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
143		copy(out[headerLen:], payload)
144		sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
145		binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
146		return out, nil
147	}
148	
149	// loadFile 只读取证地解析地图文件。
150	func loadFile(path string) (*mapState, error) {
151		raw, err := os.ReadFile(path)
152		if err != nil {
153			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
154		}
155		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
156			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
157		}
158		version := binary.BigEndian.Uint16(raw[8:10])
159		if version != fileVersion {
160			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
161		}
162		length := binary.BigEndian.Uint32(raw[10:14])
163		if int(length) != len(raw)-headerLen-4 {
164			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
165		}
166		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
167		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
168			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
169		}
170	
171		var fd fileData
172		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
173			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
174		}
175		if err := validateLoaded(&fd); err != nil {
176			return nil, err
177		}
178	
179		st := &mapState{
180			config:      fd.Config,
181			trajectory:  fd.Trajectory,
182			landmarks:   make(map[string]*landmarkState, len(fd.Landmarks)),
183			segments:    make(map[string]*segmentRecord, len(fd.Segments)),
184			sources:     make([]*frameSource, len(fd.Trajectory)-1),
185			corrections: make([]*CorrectionRecord, 0, len(fd.Corrections)),
186			corrIndex:   make(map[string]string, len(fd.Corrections)),
187		}
188		// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
189		// 无法区分也无需区分（尚无范围可校正）。
190		oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
191		for _, lm := range fd.Landmarks {
192			legacyCount := lm.LegacyCount
193			legacyMX, legacyMY := lm.LegacyMX, lm.LegacyMY
194			// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取文件中的聚合值。
195			if oldFormat {
196				legacyCount = lm.Count
197				legacyMX, legacyMY = lm.X, lm.Y
198			}
199			st.landmarks[lm.ID] = &landmarkState{
200				x:           lm.X,
201				y:           lm.Y,
202				count:       lm.Count,
203				legacyCount: legacyCount,
204				legacyMX:    legacyMX,
205				legacyMY:    legacyMY,
206			}
207		}
208		for _, sg := range fd.Segments {
209			ids := sg.Result.LandmarkIDs
210			if ids == nil {
211				ids = []string{}
212			}
213			st.segments[sg.ID] = &segmentRecord{
214				hash:   sg.Hash,
215				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
216			}
217		}
218		if !oldFormat {
219			for k, src := range fd.Sources {
220				if src == nil {
221					continue // 来自旧文件的帧：保持依据缺失
222				}
223				obs := append([]Observation(nil), src.Observations...)
224				st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
225			}
226		}
227		for _, cj := range fd.Corrections {
228			rec := &CorrectionRecord{
229				ID:        cj.ID,
230				Anchor:    cj.Anchor,
231				Target:    cj.Target,
232				EndTime:   cj.EndTime,
233				Poses:     make([]PoseChange, len(cj.Poses)),
234				Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
235			}
236			for i, pc := range cj.Poses {
237				rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
238			}
239			for i, lc := range cj.Landmarks {
240				rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Before: lc.Before, After: lc.After}
241			}
242			st.corrections = append(st.corrections, rec)
243			st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
244		}
245		return st, nil
246	}
247	
248	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
249	func validateLoaded(fd *fileData) error {
250		switch {
251		case fd.Version != int(fileVersion):
252			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
253		case len(fd.Trajectory) == 0:
254			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
255		}
256		if err := validateConfig(fd.Config); err != nil {
257			// 配置不合法不可能由本版本写出。
258			return fmt.Errorf("%w: %v", ErrCorrupt, err)
259		}
260		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
261		// 该字段（解码为 nil），数量为 0。
262		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
263			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
264		}
265		timeAt := func(t int64) bool {
266			for _, p := range fd.Trajectory {
267				if p.Time == t {
268					return true
269				}
270			}
271			return false
272		}
273		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
274		for _, lm := range fd.Landmarks {
275			if lm.ID == "" || lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
276				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
277			}
278			if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
279				return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
280			}
281			if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
282				return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
283			}
284			if _, dup := seenIDs[lm.ID]; dup {
285				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
286			}
287			seenIDs[lm.ID] = struct{}{}
288		}
289		segIDs := make(map[string]struct{}, len(fd.Segments))
290		for _, sg := range fd.Segments {
291			if sg.ID == "" || sg.Hash == "" {
292				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
293			}
294			if _, dup := segIDs[sg.ID]; dup {
295				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
296			}
297			segIDs[sg.ID] = struct{}{}
298		}
299		corrIDs := make(map[string]struct{}, len(fd.Corrections))
300		for _, cr := range fd.Corrections {
301			if cr.ID == "" || !timeAt(cr.Anchor) || !timeAt(cr.EndTime) || cr.Anchor > cr.EndTime {
302				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
303			}
304			if len(cr.Poses) == 0 {
305				return fmt.Errorf("%w: correction %s has no affected poses", ErrCorrupt, cr.ID)
306			}
307			for _, pc := range cr.Poses {
308				if !finitePose(pc.Before) || !finitePose(pc.After) {
309					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
310				}
311			}
312			if _, dup := corrIDs[cr.ID]; dup {
313				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
314			}
315			corrIDs[cr.ID] = struct{}{}
316		}
317		return nil
318	}
319	
320	func finitePose(p Pose) bool {
321		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
322	}
323	
324	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
325	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
326	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
327		h := sha256.New()
328		var b [8]byte
329		binary.BigEndian.PutUint64(b[:], uint64(anchor))
330		h.Write(b[:])
331		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
332			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
333			h.Write(b[:])
334		}
335		return fmt.Sprintf("%x", h.Sum(nil))
336	}
337	
338	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
339	func (m *Map) saveExclusive() error {
340		data, err := encodeFile(m.state)
341		if err != nil {
342			return err
343		}
344		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
345		if err != nil {
346			return err
347		}
348		return writeAndClose(f, data, m.path)
349	}
350	
351	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
352	func (m *Map) saveReplace() (err error) {
353		data, err := encodeFile(m.state)
354		if err != nil {
355			return err
356		}
357		dir, base := filepath.Split(m.path)
358		if dir == "" {
359			dir = "."
360		}
361		f, err := os.CreateTemp(dir, base+".tmp-*")
362		if err != nil {
363			return err
364		}
365		tmpName := f.Name()
366		// 任何失败路径都尽力清理临时文件。
367		defer func() {
368			if err != nil {
369				_ = os.Remove(tmpName)
370			}
371		}()
372		if err = writeAndClose(f, data, tmpName); err != nil {
373			return err
374		}
375		if err = os.Rename(tmpName, m.path); err != nil {
376			return err
377		}
378		return nil
379	}
380	
381	func writeAndClose(f *os.File, data []byte, name string) (err error) {
382		defer func() {
383			if cerr := f.Close(); err == nil {
384				err = cerr
385			}
386		}()
387		if _, err = f.Write(data); err != nil {
388			return err
389		}
390		if err = f.Sync(); err != nil {
391			return err
392		}
393		return nil
394	}
395	
396	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
397	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
398	func canonicalHash(frames []Frame) string {
399		h := sha256.New()
400		var lenBuf [4]byte
401		var numBuf [8]byte
402		putU32 := func(v uint32) {
403			binary.BigEndian.PutUint32(lenBuf[:], v)
404			h.Write(lenBuf[:])
405		}
406		putU64 := func(v uint64) {
407			binary.BigEndian.PutUint64(numBuf[:], v)
408			h.Write(numBuf[:])
409		}
410		putStr := func(s string) {
411			putU32(uint32(len(s)))
412			h.Write([]byte(s))
413		}
414	
415		putU32(uint32(len(frames)))
416		for _, fr := range frames {
417			putU64(uint64(fr.Time))
418			putU64(math.Float64bits(fr.DX))
419			putU64(math.Float64bits(fr.DY))
420			putU64(math.Float64bits(fr.DHeading))
421			putU64(math.Float64bits(fr.MoveVariance))
422			putU32(uint32(len(fr.Observations)))
423			for _, ob := range fr.Observations {
424				putStr(ob.ID)
425				putU64(math.Float64bits(ob.X))
426				putU64(math.Float64bits(ob.Y))
427			}
428		}
429		return fmt.Sprintf("%x", h.Sum(nil))
430	}
