267		cur, _ = m.CurrentPose()
268		if cur.Time != 200 || cur.X != 12 || cur.Variance != 2.25 {
269			t.Fatalf("duplicate import undid correction: %+v", cur)
270		}
271		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
272		if len(lms) != 2 {
273			t.Fatalf("landmark count = %d after duplicate import", len(lms))
274		}
275		for _, lm := range lms {
276			if (lm.ID == "L1" && lm.Count != 2) || (lm.ID == "M" && lm.Count != 1) {
277				t.Fatalf("%s count = %d after duplicate import", lm.ID, lm.Count)
278			}
279		}
280	}
