397	// writeLegacyV1File 用当前状态构造一个去掉 sources/corrections 字段的
398	// 旧版文件（二进制版本号仍为 1），模拟现网旧地图。
399	func writeLegacyV1File(t *testing.T, path string, st *mapState) {
400		t.Helper()
401		data, err := encodeFile(st)
402		if err != nil {
403			t.Fatal(err)
404		}
405		var raw map[string]any
406		if err := json.Unmarshal(data[headerLen:len(data)-4], &raw); err != nil {
407			t.Fatal(err)
408		}
409		delete(raw, "sources")
410		delete(raw, "corrections")
411		payload, err := json.Marshal(raw)
412		if err != nil {
413			t.Fatal(err)
414		}
415		out := make([]byte, headerLen+len(payload)+4)
416		copy(out[:headerLen], data[:headerLen])
417		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
418		copy(out[headerLen:], payload)
419		binary.BigEndian.PutUint32(out[len(out)-4:], crc32.ChecksumIEEE(out[:len(out)-4]))
420		if err := os.WriteFile(path, out, 0o644); err != nil {
421			t.Fatal(err)
422		}
423	}
