435			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
436		}}); err != nil {
437			t.Fatal(err)
438		}
439		writeLegacyV1File(t, path, m.state)
440		if err := m.Close(); err != nil {
441			t.Fatal(err)
442		}
443	
444		m2, err := Open(path)
445		if err != nil {
446			t.Fatalf("open legacy: %v", err)
447		}
448		defer m2.Close()
449	
450		// 旧文件可正常打开、查询。
451		p, err := m2.PoseAt(100)
452		if err != nil || p.X != 1 {
453			t.Fatalf("legacy pose: %+v %v", p, err)
454		}
455		lms, _ := m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
456		if len(lms) != 1 || lms[0].X != 1.5 || lms[0].Count != 2 {
457			t.Fatalf("legacy landmark = %v", lms)
458		}
459	
460		// 涉及旧范围的校正被拒绝并说明原因。
461		for _, anchor := range []int64{100, 200} {
462			_, err = m2.Correct(Correction{ID: "c", Anchor: anchor, Target: CorrectionTarget{X: 1}})
463			r, ok := AsRejectError(err)
464			if !ok || r.Kind != RejectNoBasis {
465				t.Fatalf("anchor %d: err = %v, want no_basis", anchor, err)
466			}
467		}
468	
469		// 旧地图上可继续导入：t=300 位姿 (2.5,0)，K 观测 (2.5,0) 距旧均值
470		// (1.5,0) 恰为合并距离，接受；K 均值变为 5.5/3，次数 3。
471		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
472			{Time: 300, DX: 0.5, Observations: []Observation{{ID: "K"}}},
473		}}); err != nil {
474			t.Fatalf("append to legacy: %v", err)
475		}
476		lms, _ = m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
477		if len(lms) != 1 || lms[0].Count != 3 {
478			t.Fatalf("K after append = %v", lms)
479		}
480		approxEq(t, "K mean after append", lms[0].X, 5.5/3.0)
481	
482		// 仅覆盖依据完整新范围的校正可成功；旧观测贡献固定不变。
483		rec, err := m2.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 2.0, Y: 0}})
484		if err != nil {
485			t.Fatalf("correct new range: %v", err)
486		}
487		if rec.EndTime != 300 || len(rec.Poses) != 1 {
488			t.Fatalf("record = %+v", rec)
489		}
490		// 新观测从 (2.5,0) 移到 (2.0,0)，与固定旧均值 (1.5,0) 距离 0.5 可接受。
491		lc := rec.Landmarks[0]
492		if lc.ID != "K" {
493			t.Fatalf("change id = %q", lc.ID)
494		}
495		approxEq(t, "K after correct", lc.After.X, (1.5*2+2.0)/3.0)
496		if lc.After.Count != 3 {
497			t.Fatalf("K count = %d", lc.After.Count)
498		}
499	
500		// 新范围校正若让新观测远离固定旧贡献，仍冲突拒绝。
501		_, err = m2.Correct(Correction{ID: "c3", Anchor: 300, Target: CorrectionTarget{X: 10, Y: 0}})
502		r, ok := AsRejectError(err)
503		if !ok || r.Kind != RejectLandmarkConflict || r.Landmark != "K" || r.Time != 300 {
504			t.Fatalf("legacy conflict err = %v", err)
505		}
506	
507		// 重开后：null 来源（旧帧）与校正记录都保持。
508		if err := m2.Close(); err != nil {
509			t.Fatal(err)
510		}
511		m3, err := Open(path)
512		if err != nil {
513			t.Fatal(err)
514		}
515		defer m3.Close()
516		if _, err := m3.Correct(Correction{ID: "x", Anchor: 100, Target: CorrectionTarget{X: 1}}); err == nil {
517			t.Fatal("old range became correctable after reopen")
518		}
519		recs, _ := m3.Corrections()
520		if len(recs) != 1 || recs[0].ID != "c2" {
521			t.Fatalf("records after legacy reopen = %v", recs)
522		}
523	}
524	
525	func TestCorrectionSaveFailureRollback(t *testing.T) {
